package com.aig.core.ui
import android.content.Context
import android.graphics.Color
import android.graphics.drawable.GradientDrawable
import android.view.ViewGroup
import android.widget.*
object UiKit{fun dp(c:Context,v:Int)=(v*c.resources.displayMetrics.density).toInt();fun column(c:Context)=LinearLayout(c).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(Color.rgb(2,4,7));setPadding(dp(c,10),dp(c,8),dp(c,10),dp(c,8))};fun label(c:Context,t:String,s:Float=15f)=TextView(c).apply{text=t;textSize=s;setTextColor(Color.rgb(225,240,250));setPadding(dp(c,4),dp(c,6),dp(c,4),dp(c,6))};fun statusLabel(c:Context,t:String)=label(c,t,13f).apply{setTextColor(Color.rgb(92,255,205));background=panelDrawable(Color.argb(205,4,16,22),Color.rgb(0,220,255));setPadding(dp(c,12),dp(c,8),dp(c,12),dp(c,8))};fun panel(c:Context)=LinearLayout(c).apply{orientation=LinearLayout.VERTICAL;background=panelDrawable(Color.argb(220,7,17,27),Color.rgb(0,205,255));setPadding(dp(c,10),dp(c,10),dp(c,10),dp(c,10))};fun skinBanner(c:Context,id:Int,h:Int=92)=ImageView(c).apply{setImageResource(id);scaleType=ImageView.ScaleType.CENTER_CROP;layoutParams=LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,dp(c,h));contentDescription="AIG RGB official skin"};fun addButton(r:ViewGroup,t:String,f:()->Unit)=RgbGlassButton(r.context).also{b->b.text=t;b.setOnClickListener{f()};r.addView(b,LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT).apply{setMargins(dp(r.context,4),dp(r.context,4),dp(r.context,4),dp(r.context,4))})};fun addWeightedButton(r:LinearLayout,t:String,f:()->Unit)=RgbGlassButton(r.context).also{b->b.text=t;b.setOnClickListener{f()};r.addView(b,LinearLayout.LayoutParams(0,dp(r.context,52),1f).apply{setMargins(dp(r.context,3),dp(r.context,3),dp(r.context,3),dp(r.context,3))})};fun toolGrid(c:Context,n:Int=4)=GridLayout(c).apply{columnCount=n;alignmentMode=GridLayout.ALIGN_BOUNDS;useDefaultMargins=false};fun addGridButton(g:GridLayout,t:String,f:()->Unit)=RgbGlassButton(g.context).also{b->b.text=t;b.setOnClickListener{f()};val col=g.childCount%g.columnCount;g.addView(b,GridLayout.LayoutParams().apply{width=0;height=dp(g.context,48);columnSpec=GridLayout.spec(col,1f);setMargins(dp(g.context,3),dp(g.context,3),dp(g.context,3),dp(g.context,3))})};fun panelDrawable(f:Int,s:Int)=GradientDrawable().apply{shape=GradientDrawable.RECTANGLE;cornerRadius=18f;setColor(f);setStroke(2,s)}}
